.dossier-eyebrow{font-size:9px;letter-spacing:.18em}.dossier-name{font-size:38px;margin:9px 0 12px;line-height:1.1}.profile-identity{font-size:11px;margin-bottom:17px}.dossier-rule{font-size:11px;gap:12px}.dossier-description{font-size:13px;line-height:1.85;margin:18px 0 23px;color:#77869a}.archive-section-heading{padding-bottom:12px;gap:10px}.archive-section-heading>span{font-size:9px}.archive-section-heading h3{font-size:13px}.radar-wrap{width:min(100%,340px);margin:5px auto 0}.radar-label{font-size:12px}.radar-value{font-size:12px}.radar-caption{font-size:10px;margin-bottom:12px}.signature-trait{padding:19px 0;gap:16px}.trait-sigil{width:37px;height:37px;font-size:21px}.trait-title{font-size:16px;margin-bottom:8px}.trait-note,.personality-copy,.personality-note p,.memory-copy{font-size:13px;line-height:1.85}.profile-motto{font-size:19px;line-height:1.75;margin:22px 0;padding-left:16px}.personality-note{padding:15px 0;gap:7px}.personality-note span{font-size:9px}.memory-entry{padding:22px 0 22px 20px}.memory-entry:before{font-size:8px;left:-4px;top:27px}.memory-entry h4{font-size:15px;margin-bottom:10px}.hero-watermark{top:18%;left:3%;max-width:94%;font-size:24vw;z-index:5}.dossier-footer{display:block;position:relative;inset:auto;order:3;margin:25px 28px;font-size:8px;color:#a1afbf}.poster-mode .archive-actions{top:17px;right:18px;gap:6px}.archive-actions button{height:40px;font-size:11px;padding:0 12px}.poster-mode .focus-counter{display:none}#characterFocus.poster-mode #focusBack{top:17px;left:16px;min-height:40px;padding:0 14px}.poster-mode #detailEdit{bottom:18px;left:18px;min-height:46px;box-shadow:0 4px 20px #52678716}.poster-mode #replayReveal{bottom:18px;right:18px;width:46px;height:46px}.poster-mode #detailMotionToggle{bottom:20px;right:75px;min-height:42px;font-size:11px}
#characterFocus.canvas-editing #posterStage.profile-screen>.spread-main{top:90px!important;height:44dvh!important}.canvas-editing .character-dossier{padding-top:48dvh;padding-bottom:44dvh}.canvas-editing .dossier-info{position:relative!important;inset:auto!important;max-height:none!important;padding:22px 24px}.canvas-editing .dossier-nav{position:relative;inset:auto}.portrait-only .character-dossier{min-height:100dvh;padding-top:0;pointer-events:none}.portrait-only #posterStage.profile-screen>.spread-main{top:12dvh!important;left:0!important;width:100%!important;height:82dvh!important;max-height:none;mask-image:linear-gradient(black 85%,transparent)}
}
@media(prefers-reduced-motion:reduce){#characterFocus #posterStage.profile-screen,#characterFocus #posterStage.profile-screen *{animation:none!important;transition:none!important}}
@media(max-width:800px){#characterFocus.poster-mode{display:block!important;align-items:initial!important;justify-content:initial!important;padding:0!important}#characterFocus.poster-mode #posterStage.profile-screen,#characterFocus.canvas-editing #posterStage.profile-screen{margin:0!important;align-self:start!important;justify-self:start!important;bottom:auto!important;right:auto!important}}
